model User {
  cloudflareTokenEnc         String? // encrypted Cloudflare API token for auto-DNS (business email)
  id                         String              @id @default(cuid())
  email                      String              @unique
  passwordHash               String
  name                       String
  // "Login with Google": the Google account's stable subject id (`sub`) once the
  // user has linked/created via Google OAuth. NULL for password-only accounts.
  // Nullable + unique so it is additive (safe `db push`) and can never point two
  // local accounts at one Google identity.
  googleId                   String?             @unique
  // Profile picture URL from Google, stored best-effort for display. Optional.
  avatarUrl                  String?
  // Discord support-bridge identity link (see lib/discord-bridge.ts,
  // app/api/admin/discord/authorize+callback/route.ts). The real Discord user
  // id ("snowflake") of the account this Nxeon staff member proved ownership
  // of via Discord OAuth (`identify` scope). Nullable + unique for the same
  // reason as `googleId` above: a Discord account can only ever be linked to
  // one Nxeon user, and a Nxeon user has at most one linked Discord account.
  // Only ever written by app/api/admin/discord/callback/route.ts, and only for
  // the CURRENTLY SIGNED-IN staff user re-derived from the real session at
  // callback time — never trust a value carried through the OAuth `state`
  // round-trip for identity. Read at Discord-reply time
  // (lib/discord-bridge.ts's `submitDiscordReply`) to resolve WHICH Nxeon
  // staff member sent a given Discord reply, replacing the old single
  // `discord_reply_as_user_id` setting now that real per-person linking exists.
  //
  // NOT YET PUSHED to the live database — same discipline as
  // `Ticket.discordThreadId` below: this column does not exist in production
  // Postgres yet, to avoid the running production app requesting a column that
  // does not exist. Run `npx prisma db push` (then `npx prisma generate`) for
  // real once this branch is reviewed and ready to promote — every read/write
  // of this field in lib/discord-bridge.ts and the OAuth routes goes through an
  // explicit `as any`/unchecked cast until then.
  discordUserId              String?             @unique
  role                       Role                @default(CUSTOMER)
  balanceCents               Int                 @default(0)
  suspended                  Boolean             @default(false)
  // When true, this account's spend/servers are excluded from admin REVENUE and
  // MRR figures — for the owner's own/test/staff accounts, so internal usage
  // never inflates the business numbers. See lib/admin-metrics.ts REVENUE_WHERE.
  excludeFromRevenue         Boolean             @default(false)
  // Self-reported acquisition source from the one-time "How did you hear about us?"
  // first-login prompt. null = not yet asked/answered; "skipped" = dismissed. Any
  // other value is the chosen channel (e.g. "google", "youtube", "other:<text>").
  heardAboutUs               String?
  createdAt                  DateTime            @default(now())
  servers                    Server[]
  transactions               WalletTransaction[]
  auditLogs                  AuditLog[]
  projects                   Project[]
  sshKeys                    SshKey[]
  tickets                    Ticket[]
  ticketMessages             TicketMessage[]
  notifications              Notification[]
  domains                    Domain[]
  invoices                   Invoice[]
  hostingAccounts            HostingAccount[]
  // Growth
  referralCode               String?             @unique
  referredById               String?
  referredBy                 User?               @relation("Referrals", fields: [referredById], references: [id])
  referrals                  User[]              @relation("Referrals")
  signupCreditCents          Int                 @default(0)
  referralRewardedAt         DateTime?
  couponRedemptions          CouponRedemption[]
  promoRedemptions           PromoRedemption[]
  // Security
  /// When this account proved control of `email` by following a verification
  /// link. NULL = unproven. Nullable, and deliberately NOT backfilled for the
  /// accounts that predate verification: stamping a timestamp onto an address
  /// nobody ever confirmed would fabricate the exact audit fact this column
  /// exists to record. Pre-existing accounts are exempted by CREATION DATE in
  /// lib/email-verification.ts instead, which leaves the data honest.
  emailVerifiedAt            DateTime?
  totpSecret                 String?
  totpSecretEnc              String?
  sessionVersion             Int                 @default(0)

model Visit {
  id          String   @id @default(cuid())
  ip          String
  path        String
  referrer    String?
  ua          String?
  // Parsed from `ua` at ingest time (lib/ua-parse.ts, ua-parser-js) — kept as
  // plain columns rather than re-parsed on every analytics read, same reasoning
  // as country/city below. deviceType is one of "Desktop"/"Mobile"/"Tablet"/
  // "Smart TV"/"Console"/"Wearable"/"XR" (UAParser has no positive "desktop"
  // signal — it's the fallback when no other type is detected). os/browser are
  // UAParser's own display names ("iOS", "Android", "Windows", "macOS", "Linux",
  // "Chrome", "Safari", "Firefox", "Edge", …) — null when ua was missing/unparseable.
  deviceType  String?
  os          String?
  browser     String?
  kind        String   @default("marketing") // marketing | portal
  userId      String?
  country     String?
  region      String?
  city        String?
  lat         Float?
  lng         Float?
  geocoded    Boolean  @default(false)
  // ---- Behaviour + attribution (additive; all nullable / defaulted, safe db push) ----
  // A stable first-party id so RECURRING vs new visitors can be told apart without
  // relying on IP (which NATs many people together and rotates for one person). Set
  // by /api/track from the `nx_vid` cookie, and CONSENT-GATED: null whenever the
  // visitor has opted out ("necessary"), so an opted-out person is only ever counted
  // by the coarse IP path, never given a durable id.
  visitorId   String? // stable per-person id (cookie), null = anon / opted-out
  sessionId   String? // per-tab visit/session id (client-scoped, 30-min idle window)
  pvid        String? // per-pageview id, so a later close-beacon can attach dwell time
  durationMs  Int? // dwell time on THIS pageview, filled in by the close beacon
  isEntry     Boolean  @default(false) // first pageview of its session (the landing page)
  utmSource   String? // ?utm_source — which ad/source sent them
  utmMedium   String? // ?utm_medium — cpc / email / social …
  utmCampaign String? // ?utm_campaign — which campaign
  // Google Ads click id (auto-tagging `?gclid=…`). Captured so paid Google clicks
  // are attributable even though they carry no utm_source; when present /api/track
  // also labels the visit google/cpc. Powers the Google Ads admin diagnostic.
  gclid       String?
  createdAt   DateTime @default(now())

  @@index([createdAt])
  @@index([ip])
  @@index([visitorId])
  @@index([sessionId])
  @@index([pvid])
  @@index([gclid])
}

/// Daily rollup of first-party visitor behaviour, maintained by the worker
/// (worker/analytics.ts, visitorRollupSweep). Keeps the admin audience dashboard's
/// trend series and long-range history cheap as the raw `Visit` log grows past what
/// is comfortable to scan live. Purely additive: nothing reads or writes it except
/// the rollup sweep and the audience page (which overlays a live "today" on top).
model VisitorDaily {
  id                String   @id @default(cuid())
  date              DateTime @unique // UTC midnight of the day this row summarises
  pageviews         Int      @default(0)
  sessions          Int      @default(0)
  uniqueVisitors    Int      @default(0) // distinct visitorId (falling back to ip)
  newVisitors       Int      @default(0) // first ever seen on this day
  returningVisitors Int      @default(0) // seen on some earlier day too
  bounces           Int      @default(0) // single-pageview sessions
  totalSessionMs    BigInt   @default(0) // Σ session dwell — divide by sessions for avg time on site
  signups           Int      @default(0) // accounts created this day
  deployed          Int      @default(0) // of those accounts, how many deployed a server
  updatedAt         DateTime @updatedAt

  @@index([date])
}

// ---- Deploy-wizard funnel + failure tracking ----
// One row per meaningful moment in a deploy wizard, emitted fire-and-forget by
// the customer wizards (components/customer/*DeployWizard.tsx) and by the
// order/provision path when it fails. `type` distinguishes the three things the
// owner needs to tell apart:
//   - "step"     : the user REACHED this step (drives the classic reach/drop-off funnel)
//   - "error"    : something FAILED on this step — a validation error, an API/
//                  provision failure, an exception. `errorCode`/`errorMessage`
//                  say WHAT tripped them up (bug vs abandonment).
//   - "complete" : the deploy SUCCEEDED (bottom of the funnel).
// All ids are nullable so an anonymous / opted-out session still records shape.
// `stepIndex` is the step's position within that session's wizard so events sort
// into wizard order even though optional steps shift the numbering.
model DeployFunnelEvent {
  id           String   @id @default(cuid())
  userId       String? // signed-in account, when resolvable server-side
  visitorId    String? // stable cookie id, when consent allows
  sessionId    String? // per-tab session id (client), the primary dedupe key
  product      String // vps | game | hosting
  step         String // wizard step label reached / that errored
  stepIndex    Int // position of that step within the session's wizard
  type         String   @default("step") // step | error | complete
  errorCode    String? // machine code for an error event (e.g. PROVISION_FAILED)
  errorMessage String? // human error text, truncated
  createdAt    DateTime @default(now())

  @@index([product, createdAt])
  @@index([product, type])
}

// ---- Geo cache (IP -> location), populated best-effort by the worker ----
model GeoCache {
  ip        String   @id
  country   String?
  region    String?
  city      String?
  lat       Float?
  lng       Float?
  createdAt DateTime @default(now())
}

// ---- Teams / organizations ----
model Organization {
  id        String       @id @default(cuid())
  name      String
  ownerId   String
  owner     User         @relation("OrgOwner", fields: [ownerId], references: [id], onDelete: Cascade)

model Server {
  id                  String           @id @default(cuid())
  name                String
  label               String? // customer-facing nickname (rename)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured by PartnerSourceCapture). Null for every direct
  // Nxeon order. Gates the webhook notify in worker/index.ts on provision success.
  partnerSource       String?
  hostname            String
  vmid                Int?             @unique
  status              ServerStatus     @default(PENDING)
  ipAddress           String?          @unique
  sshPort             Int?             @unique
  rootPassword        String?
  rootPasswordEnc     String?
  isFree              Boolean          @default(false)
  autoRenew           Boolean          @default(true)
  gameVariant         String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig          Json? // per-game settings values (validated against the family schema)
  // Minecraft-only: `<subdomain>.play.nxeon.cloud`, resolved via a per-server DNS
  // SRV record (worker/game-subdomain.ts) instead of the free tier's shared
  // mc-router — see lib/game-subdomain.ts for the shared name-validation rules.
  // Null until the customer sets one; unique across THIS column only — cross-
  // checked against FreeMinecraftServer.subdomain at the application layer since
  // Postgres can't enforce a unique constraint across two different tables.
  subdomain           String?          @unique
  suspendedNote       String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason       String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError      String?
  // Best-effort, human-readable label for whichever real provisioning phase is
  // running RIGHT NOW (e.g. "Cloning your server…", "Waiting for the game server
  // to start…") — written by worker/index.ts's provision() between real,
  // observable checkpoints (clone / config / start / guest-agent boot / SSH
  // reachable / game port open). Read by lib/provisioning-step.ts and shown by
  // <ProvisioningOverlay/> in place of its cosmetic time-based cycling text.
  // Null = no real signal available yet (falls back to the cosmetic text) or the
  // server isn't mid-provision. Never cleared explicitly — it's simply ignored
  // once status leaves PENDING/PROVISIONING.
  provisioningStep    String?
  expiresAt           DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage        Int              @default(0)
  dunningNextAt       DateTime?
  dunningPayUrl       String?
  // Sent-marker for the pre-renewal "no card on file" reminder (worker/billing.ts
  // renewalReminderSweep). Set to `now` when a card-less owner is reminded that a
  // paid server is about to renew, and reset to null when that period actually
  // renews (commitRenewal), so each cycle can remind at most once. Null = not yet
  // reminded this cycle.
  renewalReminderSentAt DateTime?
  createdAt           DateTime         @default(now())
  updatedAt           DateTime         @updatedAt
  userId              String
  user                User             @relation(fields: [userId], references: [id])
  nodeId              String?
  node                Node?            @relation(fields: [nodeId], references: [id])
  bwInBytes           BigInt           @default(0)
  bwOutBytes          BigInt           @default(0)
  abuseBwMark         BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt       DateTime? // when abuseBwMark was taken
  bwWindowStart       DateTime         @default(now())
  termMonths          Int              @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during

model HostingAccount {
  id                String                 @id @default(cuid())
  userId            String
  user              User                   @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy?product=hosting, captured by PartnerSourceCapture). Null for
  // every direct Nxeon order. Gates the webhook notify in worker/hosting.ts.
  partnerSource     String?
  hostingNodeId     String
  node              HostingNode            @relation(fields: [hostingNodeId], references: [id])
  planId            String
  plan              HostingPlan            @relation(fields: [planId], references: [id])
  // The jailed system username on the box (derived, unique per node). All the
  // account's files live under /home/<username>; its FPM pool runs AS this user.
  username          String
  primaryDomain     String // the account's main domain (name-based vhost server_name)
  status            HostingAccountStatus   @default(PENDING)
  // Effective quota snapshot (copied from the plan at creation so a plan edit
  // doesn't silently re-quota live accounts). ALWAYS already includes any purchased
  // `extraDiskGB` — it is (plan.diskGB + extraDiskGB) × 1024 — so the node's setquota
  // (taskApplyPlanLimits) never has to know about the add-on.
  diskQuotaMB       Int
  /// Purchased extra storage in GB, on TOP of the plan allowance (upsell). Add-only,
  /// mirroring Server.extraDiskGB — a live filesystem quota is only ever raised, never
  /// shrunk. Priced per-GB/month via `extra_disk_gb_price_cents` (the SAME rate VPS
  /// extra disk uses) and billed every renewal alongside the plan.
  extraDiskGB       Int                    @default(0)
  maxSites          Int
  maxDatabases      Int
  /// Billing term this account was SOLD on, in months: 1 = monthly, 12 = annual.
  /// The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan.priceCents, termMonths, annualDiscountPct)` and pushes
  /// `expiresAt` forward this many months, so an annual account renews annually at
  /// the rate it was sold — displayed === charged === renewed. Defaults to 1 so
  /// every pre-existing row keeps billing monthly exactly as before.
  termMonths        Int                    @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS account's term was sold — a
  /// snapshot of `annual_discount_percent` frozen at sale, exactly like
  /// Server.annualDiscountPct. The renewal reads THIS (falling back to the live
  /// setting when null) so an annual account renews at the sold rate even if the
  /// admin retunes the discount afterwards. NULL on monthly accounts and on rows
  /// that predate this column — the live setting is used for those, which for a
  /// monthly term changes nothing.
  annualDiscountPct Float?
  // PHP version the account's FPM pool runs (within the plan's allowed set).
  phpVersion        String                 @default("8.3")
  // HTTPS: set once a per-domain Let's Encrypt cert is issued (SNI on the shared
  // IP). The SSL sweep flips this after the domain resolves to us.
  sslActive         Boolean                @default(false)
  // Live disk/inode usage, refreshed by hostingUsageSweep (null until first
  // measured). Powers the real usage meters in the customer panel.
  diskUsedMB        Int?
  inodesUsed        Int?
  usageAt           DateTime?
  // Serve-verification health, refreshed by hostingHealthSweep (null until first
  // checked). serveHttpOk/serveHttpsOk record whether nginx actually answers on
  // 80/443 for this domain from the node — the guardrail against a customer ever
  // seeing ERR_CONNECTION_REFUSED while the panel claims "active". healthNote is a
  // short human string for the DNS→HTTPS stepper; healthCheckedAt timestamps it.
  // recheckRequested is set by the customer "Check now / Go live" button so the
  // sweep picks that account up before its normal cadence, then clears it.
  serveHttpOk       Boolean?
  serveHttpsOk      Boolean?
  healthNote        String?
  healthCheckedAt   DateTime?
  recheckRequested  Boolean                @default(false)
  // The account's SFTP/login password, encrypted; set at provision and shown to
  // the customer ONCE, then cleared. (SFTP is a reviewed later phase.)
  sftpPasswordEnc   String?
  // The per-account, hard-to-guess URL path where the Adminer DB manager is
  // dropped inside this account's own webroot (e.g. /nxtools-<random>/adminer.php),
  // served by this account's own PHP-FPM socket. Null until the customer installs
  // it from the Databases tab. A leaked path yields no cross-tenant access: the
  // customer must still log in with their OWN scoped DB user (localhost, granted on
  // their databases only). See INSTALL_DBTOOL in worker/hosting.ts.
  dbToolPath        String?
  // Proprietary in-portal DB manager (Nxeon-built, replaces Adminer). A single
  // account-level MySQL user granted on `<username>\_%`.* ONLY — i.e. every one of
  // this account's databases and NOTHING else (db-scoped grant, so no global
  // FILE/PROCESS/SUPER either). Its password is encrypted AT REST (persistent,
  // like sftpPasswordEnc) because the manager re-authenticates as this user on
  // every query, server-side — the credential is NEVER sent to the browser. The
  // ENSURE_DBMGR task creates the user on the node; dbMgrReady flips true when it
  // succeeds. See lib/hosting-db.ts + lib/actions-hosting-db.ts.
  dbMgrUser         String?
  dbMgrPassEnc      String?
  dbMgrReady        Boolean                @default(false)
  // Provisioning bookkeeping.
  error             String?
  // Best-effort, human-readable label for whichever real provisioning step is
  // running right now (e.g. "Creating your account…", "Configuring your web
  // server…") — written by worker/hosting.ts's provisionHostingAccount() /
  // applyIsolation() between real, observable command groups. Read (alongside a
  // live HostingTask, e.g. a queued WordPress install) by
  // lib/provisioning-step.ts and shown by <ProvisioningOverlay/>. Null = no real
  // signal yet (falls back to a generic message) or not mid-provision.
  provisioningStep  String?
