model EmailSubscription {
  id                String    @id @default(cuid())
  userId            String
  user              User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  domainName        String
  emailPlanId       String
  emailPlan         EmailPlan @relation(fields: [emailPlanId], references: [id])
  status            String    @default("ACTIVE") // ACTIVE | SUSPENDED | CANCELLED
  verified          Boolean   @default(false)
  verifyToken       String?
  verifiedAt        DateTime?
  external          Boolean   @default(false) // domain registered outside Nxeon
  dkimRecord        String? // cached DKIM TXT value from Mailcow
  autoRenew         Boolean   @default(true)
  /// Billing term this subscription was SOLD on, in months: 1 = monthly, 12 =
  /// annual. The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan monthly, termMonths, annualDiscountPct)` and advances
  /// `expiresAt` this many months, so an annual subscription renews annually at the
  /// sold rate — displayed === charged === renewed. Defaults to 1 so pre-existing
  /// rows keep renewing on their plan's period exactly as before.
  termMonths        Int       @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS subscription's term was sold
  /// — snapshot of `annual_discount_percent` frozen at sale (like
  /// Server.annualDiscountPct). Renewal reads THIS (null → live setting) so an
  /// annual sub renews at the sold rate even if the admin retunes afterwards.
  annualDiscountPct Float?
  createdAt         DateTime  @default(now())
  expiresAt         DateTime?
  mailboxes         Mailbox[]
}

model Mailbox {
  id                 String            @id @default(cuid())
  subscriptionId     String
  subscription       EmailSubscription @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)
  // GLOBALLY unique — every Mailcow call is keyed by this address string on one
  // shared instance, so two rows naming the same address are two customers
  // pointing at ONE real mailbox. That was the data-layer half of the 2026-07-25
  // cross-tenant takeover: an attacker created admin@victim.com under their own
  // subscription and reset "their" password, which rewrote the victim's live
  // mailbox. The application checks are fixed too, but this constraint is what
  // makes the class of bug impossible rather than merely absent today.
  address            String            @unique // full email address
  passwordEnc        String? // encrypted mailbox password (if self-provisioned)
  status             String            @default("PROVISIONING") // PROVISIONING | ACTIVE | SUSPENDED | FAILED
  quotaMB            Int? // mailbox quota in MB (from the plan tier)
  createdAt          DateTime          @default(now())
  signature          String? // legacy / derived plain-text signature (fallback)
  displayName        String?
  autoReplyEnabled   Boolean           @default(false)
  autoReplySubject   String?
  autoReplyBody      String?
  // --- Rich signature (native webmail) ---
  signatureHtml      String? // sanitized rich-signature HTML (source of truth)
  signatureEnabled   Boolean           @default(true)
  signatureOnReply   Boolean           @default(true)
  signaturePlacement String            @default("below") // "above" | "below" the quoted text
  // --- Identity ---
  replyTo            String?
  organization       String?
  // --- Auto-reply date window ---
  autoReplyStart     DateTime?
  autoReplyEnd       DateTime?
  // --- Forwarding (stored) ---
  forwardingAddress  String?
  forwardKeepCopy    Boolean           @default(true)
}

// ---- Block storage volumes (add-on disks) ----
