import { PrismaClient } from "@prisma/client";
const p = new PrismaClient();

function pct(n: number, d: number) {
  return d === 0 ? "0.0%" : ((n / d) * 100).toFixed(1) + "%";
}
const line = (s = "") => console.log(s);
const H = (s: string) => { line(); line("================ " + s + " ================"); };

async function main() {
  // ---------- Baselines ----------
  const totalVisits = await p.visit.count();
  const dateMin = await p.visit.findFirst({ orderBy: { createdAt: "asc" }, select: { createdAt: true } });
  const dateMax = await p.visit.findFirst({ orderBy: { createdAt: "desc" }, select: { createdAt: true } });
  const totalUsers = await p.user.count();
  const usersExclRevenue = await p.user.count({ where: { excludeFromRevenue: true } });
  const totalServers = await p.server.count();
