    const host = (() => { try { return new URL(r.referrer!).hostname.toLowerCase(); } catch { return ref; } })();
    // paid first (gclid or cpc)
    if (r.gclid || um === "cpc" || um === "ppc" || um === "paid") { buckets["Google Ads (paid)"]++; continue; }
    const aihit = AI.find(a => ref.includes(a) || us.includes(a.split(".")[0]));
    if (aihit) { buckets["AI assistants (ChatGPT/Perplexity/etc)"]++; aiDetail[aihit] = (aiDetail[aihit] || 0) + 1; continue; }
    if (!ref && !us) { buckets["Direct / none"]++; continue; }
    if (INTERNAL.some(i => ref.includes(i) || us.includes(i))) { buckets["Internal (own domains)"]++; continue; }
    if (ref.includes("google.") || us === "google") { buckets["Google organic"]++; continue; }
    if (ref.includes("bing.") || ref.includes("duckduckgo") || ref.includes("yahoo") || ref.includes("yandex") || ref.includes("ecosia") || ref.includes("baidu") || ref.includes("brave")) { buckets["Other search engines"]++; continue; }
    const soc = SOCIAL.find(s => ref.includes(s) || us.includes(s.split(".")[0]));
