  line("-- Top 'other referral' hosts --");
  for (const [k, v] of Object.entries(otherRefDetail).sort((a, b) => b[1] - a[1]).slice(0, 20)) line(`  ${k}: ${v}`);

  // utm source/medium raw
  line("\n-- utmSource (non-null) top --");
  const utmS: any[] = await p.$queryRawUnsafe(`SELECT "utmSource" s, COUNT(*)::int c FROM "Visit" WHERE "utmSource" IS NOT NULL GROUP BY 1 ORDER BY c DESC LIMIT 15`);
  for (const r of utmS) line(`  ${r.s}: ${r.c}`);
  line("-- utmMedium (non-null) top --");
  const utmM: any[] = await p.$queryRawUnsafe(`SELECT "utmMedium" m, COUNT(*)::int c FROM "Visit" WHERE "utmMedium" IS NOT NULL GROUP BY 1 ORDER BY c DESC LIMIT 15`);
  for (const r of utmM) line(`  ${r.m}: ${r.c}`);
  const gclidCount = await p.visit.count({ where: { gclid: { not: null } } });
  line(`-- gclid present (Google Ads clicks): ${gclidCount}`);

  // ---------- 3. TOP LANDING PAGES ----------
  H("3. TOP LANDING PAGES (isEntry=true)");
  const totalEntries = await p.visit.count({ where: { isEntry: true } });
  line(`Total entry pageviews (sessions w/ landing): ${totalEntries}`);
  const landings: any[] = await p.$queryRawUnsafe(`
    SELECT path, kind, COUNT(*)::int c FROM "Visit" WHERE "isEntry"=true GROUP BY 1,2 ORDER BY c DESC LIMIT 30`);
  line("path | kind | entries | %ofentries");
  for (const r of landings) line(`${r.path} | ${r.kind} | ${r.c} | ${pct(r.c, totalEntries)}`);

  // ---------- 4. TOP PAGES OVERALL ----------
