  const pages: any[] = await p.$queryRawUnsafe(`SELECT path, kind, COUNT(*)::int c FROM "Visit" GROUP BY 1,2 ORDER BY c DESC LIMIT 30`);
  line("path | kind | pageviews | %");
  for (const r of pages) line(`${r.path} | ${r.kind} | ${r.c} | ${pct(r.c, totalVisits)}`);

  await p.$disconnect();
}
main().catch(e => { console.error(e); process.exit(1); });

