// Reusable source classifier
const AI = ["chatgpt", "openai", "chat.openai", "perplexity", "claude.ai", "anthropic", "gemini", "bard.google", "copilot", "bing.com/chat", "you.com", "poe.com", "phind"];
const SOCIAL = ["reddit", "t.co", "twitter", "x.com", "facebook", "fb.com", "instagram", "discord", "youtube", "youtu.be", "linkedin", "tiktok", "pinterest", "quora", "telegram"];
const INTERNAL = ["nxeon.cloud", "nxeon.com", "studionexis", "kodely", "localhost", "127.0.0.1"];
function classify(r: { referrer: string | null; utmSource: string | null; utmMedium: string | null; gclid: string | null }): string {
  const ref = (r.referrer || "").toLowerCase();
  const um = (r.utmMedium || "").toLowerCase();
  const us = (r.utmSource || "").toLowerCase();
  if (r.gclid || um === "cpc" || um === "ppc" || um === "paid") return "Google Ads (paid)";
  if (AI.find(a => ref.includes(a) || us.includes(a.split(".")[0]))) return "AI assistants";
  if (!ref && !us) return "Direct / none";
  if (INTERNAL.some(i => ref.includes(i) || us.includes(i))) return "Internal (own domains)";
  if (ref.includes("google.") || us === "google") return "Google organic";
  if (ref.includes("bing.") || ref.includes("duckduckgo") || ref.includes("yahoo") || ref.includes("yandex") || ref.includes("ecosia") || ref.includes("baidu")) return "Other search";
  if (SOCIAL.find(s => ref.includes(s) || us.includes(s.split(".")[0]))) return "Social";
  return "Other referral";
}

