async function main() {
  // ---------- Build buyer set with first-purchase time ----------
  const firstBuy: Record<string, Date> = {};
  const add = (uid: string, d: Date) => { if (!firstBuy[uid] || d < firstBuy[uid]) firstBuy[uid] = d; };
  for (const s of await p.server.findMany({ where: { isFree: false }, select: { userId: true, createdAt: true } })) add(s.userId, s.createdAt);
  for (const s of await p.hostingAccount.findMany({ select: { userId: true, createdAt: true } })) add(s.userId, s.createdAt);
  for (const s of await p.emailSubscription.findMany({ select: { userId: true, createdAt: true } })) add(s.userId, s.createdAt);
  const staffIds = new Set((await p.user.findMany({ where: { excludeFromRevenue: true }, select: { id: true } })).map(u => u.id));
  const buyers = Object.keys(firstBuy).filter(id => !staffIds.has(id));

  H("6. PURCHASE PATHS — content viewed before first purchase (userId-linked)");
  line(`Paying (non-staff) buyers analysed: ${buyers.length}`);
  const prePathAll: Record<string, number> = {};
  const prePathMkt: Record<string, number> = {};
  const landingOfBuyers: Record<string, number> = {};
  let buyersWithVisits = 0;
  const perBuyer: string[] = [];
  for (const uid of buyers) {
    const u = await p.user.findUnique({ where: { id: uid }, select: { email: true, createdAt: true, heardAboutUs: true } });
    // gather visitorIds this user ever used
    const vids = (await p.visit.findMany({ where: { userId: uid, visitorId: { not: null } }, select: { visitorId: true }, distinct: ["visitorId"] })).map(v => v.visitorId!);
    const orClause: any[] = [{ userId: uid }];
    if (vids.length) orClause.push({ visitorId: { in: vids } });
    const visits = await p.visit.findMany({
      where: { AND: [{ OR: orClause }, { createdAt: { lte: firstBuy[uid] } }] },
      select: { path: true, kind: true, isEntry: true, referrer: true, createdAt: true, utmSource: true },
      orderBy: { createdAt: "asc" },
    });
    if (visits.length) buyersWithVisits++;
    const seenPaths = new Set<string>();
    for (const v of visits) {
      if (!seenPaths.has(v.path)) { seenPaths.add(v.path); prePathAll[v.path] = (prePathAll[v.path] || 0) + 1; if (v.kind === "marketing") prePathMkt[v.path] = (prePathMkt[v.path] || 0) + 1; }
      if (v.isEntry) landingOfBuyers[v.path] = (landingOfBuyers[v.path] || 0) + 1;
    }
    const firstMkt = visits.find(v => v.kind === "marketing");
