  }
  line(`Buyers with ANY linkable pre-purchase visit: ${buyersWithVisits}/${buyers.length}`);
  line("\n-- Per-buyer journey summary --");
  perBuyer.forEach(l => line(l));
  line("\n-- MARKETING pages appearing in buyers' pre-purchase journeys (count = # of buyers who saw it) --");
  for (const [k, v] of Object.entries(prePathMkt).sort((a, b) => b[1] - a[1]).slice(0, 25)) line(`  ${k}: ${v}`);
  line("\n-- Buyer LANDING pages (first touch of the session) --");
  for (const [k, v] of Object.entries(landingOfBuyers).sort((a, b) => b[1] - a[1]).slice(0, 20)) line(`  ${k}: ${v}`);

