  const prodTypes: any[] = await p.$queryRawUnsafe(`SELECT product, type, COUNT(*)::int c FROM "DeployFunnelEvent" GROUP BY 1,2 ORDER BY 1,2`);
  line("product | type | events");
  for (const r of prodTypes) line(`  ${r.product} | ${r.type} | ${r.c}`);
  for (const prod of ["vps", "game", "hosting"]) {
    line(`\n-- ${prod.toUpperCase()} funnel --`);
    const started: any[] = await p.$queryRawUnsafe(`SELECT COUNT(DISTINCT COALESCE("sessionId","visitorId","userId","id"))::int c FROM "DeployFunnelEvent" WHERE product=$1`, prod);
    const completed: any[] = await p.$queryRawUnsafe(`SELECT COUNT(DISTINCT COALESCE("sessionId","visitorId","userId","id"))::int c FROM "DeployFunnelEvent" WHERE product=$1 AND type='complete'`, prod);
    const startedN = started[0]?.c || 0, completedN = completed[0]?.c || 0;
    line(`  distinct sessions that entered wizard: ${startedN}; completed: ${completedN}; completion rate: ${pct(completedN, startedN)}`);
    const steps: any[] = await p.$queryRawUnsafe(`SELECT step, MIN("stepIndex")::int idx, COUNT(DISTINCT COALESCE("sessionId","visitorId","userId","id"))::int sessions FROM "DeployFunnelEvent" WHERE product=$1 AND type='step' GROUP BY step ORDER BY idx`, prod);
    line("  step-by-step reach (distinct sessions):");
    for (const s of steps) line(`    [${s.idx}] ${s.step}: ${s.sessions} (${pct(s.sessions, startedN)} of starters)`);
    const errs: any[] = await p.$queryRawUnsafe(`SELECT COALESCE("errorCode",'(none)') ec, step, COUNT(*)::int c FROM "DeployFunnelEvent" WHERE product=$1 AND type='error' GROUP BY 1,2 ORDER BY c DESC LIMIT 10`, prod);
    if (errs.length) { line("  errors:"); for (const e of errs) line(`    ${e.ec} @ ${e.step}: ${e.c}`); }
  }

  // ---------- 8. DEVICE ----------
