  const dev: any[] = await p.$queryRawUnsafe(`SELECT COALESCE("deviceType",'(unknown)') d, COUNT(*)::int c FROM "Visit" GROUP BY 1 ORDER BY c DESC`);
  const devTotal = dev.reduce((a, r) => a + r.c, 0);
  line("ALL visits:"); for (const r of dev) line(`  ${r.d}: ${r.c} (${pct(r.c, devTotal)})`);
  const devMkt: any[] = await p.$queryRawUnsafe(`SELECT COALESCE("deviceType",'(unknown)') d, COUNT(*)::int c FROM "Visit" WHERE kind='marketing' GROUP BY 1 ORDER BY c DESC`);
  const devMktTotal = devMkt.reduce((a, r) => a + r.c, 0);
  line("MARKETING visits (browsers):"); for (const r of devMkt) line(`  ${r.d}: ${r.c} (${pct(r.c, devMktTotal)})`);
  // buyers' device (by unique visitor first entry)
  if (buyers.length) {
    const devBuy: any[] = await p.$queryRawUnsafe(`SELECT COALESCE("deviceType",'(unknown)') d, COUNT(*)::int c FROM "Visit" WHERE "userId" = ANY($1) GROUP BY 1 ORDER BY c DESC`, buyers);
    const devBuyTotal = devBuy.reduce((a, r) => a + r.c, 0);
    line("BUYERS' visits (userId-tagged):"); for (const r of devBuy) line(`  ${r.d}: ${r.c} (${pct(r.c, devBuyTotal)})`);
  }
  // OS + browser quick
  const os: any[] = await p.$queryRawUnsafe(`SELECT COALESCE(os,'(unknown)') o, COUNT(*)::int c FROM "Visit" WHERE kind='marketing' GROUP BY 1 ORDER BY c DESC LIMIT 8`);
  line("Marketing OS: " + os.map(r => `${r.o}=${r.c}`).join(", "));
  const br: any[] = await p.$queryRawUnsafe(`SELECT COALESCE(browser,'(unknown)') b, COUNT(*)::int c FROM "Visit" WHERE kind='marketing' GROUP BY 1 ORDER BY c DESC LIMIT 8`);
  line("Marketing browser: " + br.map(r => `${r.b}=${r.c}`).join(", "));

  // ---------- 9. NEW vs RETURNING + BOUNCE (VisitorDaily) ----------
  H("9. NEW vs RETURNING + BOUNCE (VisitorDaily rollups)");
  const vd = await p.visitorDaily.findMany({ orderBy: { date: "asc" } });
  const sum = (f: (x: any) => number) => vd.reduce((a, r) => a + f(r), 0);
  const sN = sum(r => r.newVisitors), sR = sum(r => r.returningVisitors), sSess = sum(r => r.sessions), sB = sum(r => r.bounces), sPV = sum(r => r.pageviews), sSignup = sum(r => r.signups), sDep = sum(r => r.deployed), sMs = vd.reduce((a, r) => a + Number(r.totalSessionMs), 0);
  line(`Days rolled up: ${vd.length}`);
  line(`Pageviews: ${sPV}; Sessions: ${sSess}; New visitors: ${sN}; Returning: ${sR}; New:Return ratio = ${pct(sN, sN + sR)} new / ${pct(sR, sN + sR)} returning`);
  line(`Bounces: ${sB} => bounce rate ${pct(sB, sSess)} of sessions`);
  line(`Avg session dwell: ${sSess ? (sMs / sSess / 1000).toFixed(0) : 0}s`);
  line(`Signups (rolled): ${sSignup}; Deployed (rolled): ${sDep}`);
  line("\n-- Weekly trend --");
